// Backfill existing Parse rows into Meilisearch (lexical). Safe to re-run.
// Conversations and end-users power the app-wide search; FAQs are indexed
// lexically here so search works before re-ingestion — their vectors are
// (re)generated by the app's per-model reindex / ingestion (which has the
// embedding model). Documents are added by id, so re-runs never duplicate.
//
//   bun scripts/reindex.mjs

import { assertEnv, parseFetch } from './parseRest.mjs'

const HOST = String(process.env.MEILI_URL || '').replace(/\/+$/, '')
const KEY = process.env.MEILI_MASTER_KEY

async function meiliAdd(uid, docs) {
  if (!docs.length) return
  const res = await fetch(`${HOST}/indexes/${uid}/documents`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...(KEY ? { Authorization: `Bearer ${KEY}` } : {}) },
    body: JSON.stringify(docs)
  })
  if (!res.ok) throw new Error(`meili add ${uid} → ${res.status}`)
}

async function* pages(className, extraQuery = '') {
  let skip = 0
  const limit = 500
  for (;;) {
    const res = await parseFetch(`/classes/${className}?limit=${limit}&skip=${skip}${extraQuery}`)
    if (!res.ok) throw new Error(`Parse ${className} → ${res.status}`)
    const rows = res.body.results || []
    if (!rows.length) break
    yield rows
    if (rows.length < limit) break
    skip += limit
  }
}

const time = (v) => (v ? new Date(v).getTime() : 0)

async function main() {
  assertEnv()
  if (!HOST) { console.log('MEILI_URL not set — nothing to reindex.'); return }

  let convos = 0
  for await (const rows of pages('Conversation', '&include=endUser')) {
    await meiliAdd('conversations', rows.map(c => ({
      id: c.objectId,
      projectId: c.project?.objectId || '',
      endUserId: c.endUser?.objectId || '',
      endUserName: c.endUser?.name || '',
      endUserEmail: c.endUser?.email || '',
      subject: c.subject || '',
      preview: c.lastMessagePreview || '',
      status: c.status || 'open',
      lastMessageAt: time(c.lastMessageAt?.iso || c.lastMessageAt)
    })))
    convos += rows.length
  }

  let users = 0
  for await (const rows of pages('EndUser')) {
    await meiliAdd('endusers', rows.map(u => ({
      id: u.objectId, projectId: u.project?.objectId || '', name: u.name || '', email: u.email || '', externalId: u.externalId || ''
    })))
    users += rows.length
  }

  let faqs = 0
  for await (const rows of pages('Faq', '&include=node')) {
    await meiliAdd('knowledge', rows.map(f => {
      const pathCache = f.node?.pathCache || ''
      const parts = pathCache ? pathCache.split('/') : []
      return {
        id: f.objectId,
        modelId: f.knowledgeModel?.objectId || '',
        nodeId: f.node?.objectId || '',
        pathCache,
        pathAncestors: parts.map((_, i) => parts.slice(0, i + 1).join('/')),
        status: f.status || 'draft',
        language: f.language || 'en',
        question: f.question || '',
        aliases: f.aliases || [],
        keywords: f.keywords || [],
        tags: f.tags || [],
        answer: f.answer || '',
        updatedAt: time(f.updatedAt)
      }
    }))
    faqs += rows.length
  }

  console.log(`Reindexed: ${convos} conversations, ${users} end-users, ${faqs} FAQs (lexical).`)
  console.log('FAQ vectors: run a per-model reindex in the admin panel (or re-import) to (re)generate embeddings.')
}

main().catch((error) => { console.error(error.message || error); process.exit(1) })
